{
  "themes": [
    {
      "cluster": 12,
      "name": "Poor Audio Quality",
      "description": "Users report low sound quality, distortion at high volume, and lack of improvement despite high‑quality streaming settings."
    },
    {
      "cluster": 13,
      "name": "Offline Playback Failures",
      "description": "Downloaded songs often become unplayable offline, with the app incorrectly showing no internet connection."
    },
    {
      "cluster": 14,
      "name": "False No‑Internet Errors",
      "description": "The app frequently displays a “no internet connection” message even when Wi‑Fi or mobile data is working."
    },
    {
      "cluster": 15,
      "name": "Unexpected Log‑Outs",
      "description": "Users are logged out unexpectedly, especially while driving, and must repeatedly re‑enter credentials."
    },
    {
      "cluster": 16,
      "name": "Positive Music Discovery Praise",
      "description": "Customers love the music recommendations and overall listening experience, describing the app as the best for discovering songs."
    },
    {
      "cluster": 17,
      "name": "Playlist Playback Mismatch",
      "description": "Songs added to playlists or favorites either skip automatically or play unrelated tracks, frustrating users."
    },
    {
      "cluster": 18,
      "name": "Premium Payment & Access Issues",
      "description": "Premium features are unavailable or payment methods are unsupported, especially in certain countries."
    },
    {
      "cluster": 19,
      "name": "Login Failures",
      "description": "Repeated attempts to log in—using email, phone, or new accounts—result in errors and prevent access."
    },
    {
      "cluster": 20,
      "name": "UI Glitches and Stuck Tracks",
      "description": "The interface sometimes shows previous songs, fails to display current tracks, or stops playback unexpectedly."
    },
    {
      "cluster": 21,
      "name": "Limited Skips Per Hour",
      "description": "Users are restricted to a small number of song skips each hour, hindering playlist navigation."
    },
    {
      "cluster": 22,
      "name": "Excessive Advertisements",
      "description": "Frequent and long ads interrupt listening, with users noting multiple ads in short intervals."
    },
    {
      "cluster": 23,
      "name": "App Crashes After Updates",
      "description": "Recent updates cause the app to crash frequently, even when opening menus or performing basic actions."
    }
  ]
}
